const crypto = require('crypto');
const envelope = $input.first().json.body;
const secret = $env.AUTOMATION_SECRET;
if (!secret || secret.length < 32) throw new Error('Missing automation configuration');
if (!envelope || typeof envelope.payload !== 'string' || envelope.payload.length > 4096 || !Number.isSafeInteger(envelope.timestamp) || Math.abs(Date.now()-envelope.timestamp)>300000 || !/^[0-9a-f]{64}$/.test(envelope.signature||'')) throw new Error('Invalid signature envelope');
const expected=crypto.createHmac('sha256',secret).update(`${envelope.timestamp}\n${envelope.payload}`).digest();
if(!crypto.timingSafeEqual(expected,Buffer.from(envelope.signature,'hex')))throw new Error('Invalid signature');
const event=JSON.parse(envelope.payload);
if(!['requested','approved','declined','returned'].includes(event.kind)||typeof event.eventId!=='string'||typeof event.loanId!=='string'||typeof event.recipient!=='string')throw new Error('Invalid event');
// Deliberately a logged mock notification, as permitted by the assignment.
// A real provider must use eventId as its idempotency key; transport is at-least-once.
console.log('lendloop.notification.mock',{eventId:event.eventId,loanId:event.loanId,recipient:event.recipient,kind:event.kind});
return [{json:{accepted:true,eventId:event.eventId}}];
